BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats11-q01', '分散分析と多重比較',
   '3種類の肥料A・B・Cで育てた野菜の重さを比べたい。「AとB」「BとC」「AとC」というふうに2つずつ組にしてt検定を3回繰り返すやり方には、どんな問題がある？',
   NULL::text,
   '["比べる回数が増えるほど、誤って「差がある」と判定してしまう危険が積み重なっていく", "t検定という計算方法そのものが、3種類以上の野菜には使えない計算式になってしまう", "肥料の種類が多いほど、野菜の重さの測定そのものの誤差が大きくなってしまう", "組にする回数が増えるほど、必要なデータの個数がどんどん少なくて済むようになる"]',
   0, '[0]', 'single',
   '{"asked": "3群以上を比べたいときに、2群ずつのt検定を繰り返すと何が問題になるか。", "point": "比較の回数が増えるほど、どこか1回でも偶然「差がある」と出てしまう危険は積み重なって膨らむ。", "kid": "コインを1回投げて表が出る確率は低くても、何回も投げ続ければそのうち1回は表が出やすくなる。それと同じで、t検定を何回も繰り返すほど、そのうちどれか1回はたまたま「差がある」と出てしまいやすくなる。", "eg": "くじを1回引いて当たる確率が5%だとしても、同じくじを3回引けば「3回のうち1回でも当たる」確率は5%よりずっと高くなる。t検定を3回繰り返すのも、これと同じしくみで「誤って当たり(差あり)を引いてしまう」確率が上がる。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">3群を2つずつ比べると、t検定が3回必要</text><line x1=\"80\" y1=\"55\" x2=\"260\" y2=\"55\" stroke=\"#60a5fa\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\"/><line x1=\"80\" y1=\"55\" x2=\"170\" y2=\"105\" stroke=\"#60a5fa\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\"/><line x1=\"260\" y1=\"55\" x2=\"170\" y2=\"105\" stroke=\"#60a5fa\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\"/><circle cx=\"80\" cy=\"55\" r=\"16\" fill=\"#3b82f6\"/><circle cx=\"260\" cy=\"55\" r=\"16\" fill=\"#3b82f6\"/><circle cx=\"170\" cy=\"105\" r=\"16\" fill=\"#3b82f6\"/><text x=\"80\" y=\"59\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"700\">A</text><text x=\"260\" y=\"59\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"700\">B</text><text x=\"170\" y=\"109\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"700\">C</text><text x=\"170\" y=\"42\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">t検定</text><text x=\"98\" y=\"88\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">t検定</text><text x=\"242\" y=\"88\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">t検定</text><text x=\"170\" y=\"128\" fill=\"#c9a04a\" font-size=\"9.5\" text-anchor=\"middle\">比べる回数が増えるほど誤検出の危険が膨らむ</text></svg>", "terms": [["多重性の問題", "検定を何度も繰り返すと、誤って「差がある」と判定してしまう危険が積み重なること"], ["t検定", "2つの群の平均に差があるかどうかを調べる検定"]], "think": "なぜ回数を重ねるとまずいのかがカギ。t検定を1回行うとき、本当は差がないのに誤って「差がある」と判定してしまう危険は、有意水準ぶんだけ最初から織り込まれている。この危険は1回なら小さくても、AB・BC・ACと3回繰り返すと、そのうちどれか1回で誤判定してしまう危険はどんどん積み上がっていく。これが3群以上を比べるときにペアごとのt検定を単純に繰り返してはいけない理由。", "vs": "「t検定を3回やれば3群まとめて比べたことになる」と考えがちだが、それぞれのt検定は独立した1回の判定。3回分の誤判定の危険が積み重なることを見落とすと、本当は差がないのに「差がある」と結論づけてしまいやすくなる。", "why_asked": "3群以上を比べる場面はテストの3クラス比較、3種類の薬の効果比較など日常的に多い。ここで安易にt検定を繰り返すと、統計の教科書で必ず注意される落とし穴を踏むことになる。この後に出てくる分散分析は、この落とし穴を避けるための方法。", "usecase": "複数の広告パターンの効果比較、複数の製造ラインの品質比較など、3つ以上のグループを同時に比べたい場面全般。", "opt": ["正解。3回のt検定それぞれで生まれる誤判定の危険が積み重なり、どこかで偶然「差がある」と出てしまいやすくなる。", "t検定の計算式そのものは何群であっても2群ずつなら計算できる。使えなくなるわけではなく、繰り返す回数が問題になる。", "野菜の重さの測定誤差は、検定を何回繰り返すかとは関係なく、測定のしかたで決まるもの。", "組にする回数が増えても、必要なデータの個数が減るわけではない。むしろ比較のたびに同じだけのデータが要る。"]}'),

  ('stats11-q02', '分散分析と多重比較',
   '3種類の肥料A・B・Cで育てた野菜の重さを、ペアごとのt検定ではなく、群と群の間のばらつきと、同じ群の中のばらつきの比を見ることで、一度に比べる方法を何という？',
   NULL::text,
   '["分散分析", "t検定", "カイ二乗検定", "回帰分析"]',
   0, '[0]', 'single',
   '{"asked": "3群以上を、ペアごとのt検定を繰り返さずに一度に比べる方法の名前（英語ではANOVAと呼ぶ）。", "point": "分散分析（ANOVA）は、群と群の間のばらつきと、同じ群の中のばらつきの「比」を見て、3群以上を1回の検定でまとめて比べる方法。", "kid": "分散分析は、「群による違い」と「同じ群の中での自然なばらつき」の2種類のばらつきを見比べて、「群によって本当に差があるといえそうか」を1回の手続きで判定する方法。", "eg": "3クラスのテストの平均点を比べるとき、クラスどうしの平均点の差(群間のばらつき)が、同じクラス内での1人ひとりの点数のばらつき(群内のばらつき)に比べて目立つかどうかを見る。目立てば「クラスによる差がありそう」と言える。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">分散分析＝2種類のばらつきの比を1回で見る</text><rect x=\"20\" y=\"32\" width=\"150\" height=\"22\" fill=\"#2a2f3f\"/><text x=\"95\" y=\"47\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">t検定×3回（ペアごと）</text><rect x=\"170\" y=\"32\" width=\"150\" height=\"22\" fill=\"#3b82f6\"/><text x=\"245\" y=\"47\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">分散分析×1回</text><line x1=\"170\" y1=\"32\" x2=\"170\" y2=\"54\" stroke=\"#141720\" stroke-width=\"1.5\"/><text x=\"170\" y=\"75\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">同じ結論を、1回の手続きで出せる</text><circle cx=\"70\" cy=\"100\" r=\"12\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"70\" y=\"104\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">群間</text><text x=\"70\" y=\"124\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">群どうしのばらつき</text><circle cx=\"270\" cy=\"100\" r=\"12\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><text x=\"270\" y=\"104\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">群内</text><text x=\"270\" y=\"124\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">群の中のばらつき</text><text x=\"170\" y=\"104\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\">÷</text></svg>", "terms": [["分散分析（ANOVA）", "群間のばらつきと群内のばらつきの比を見て、3群以上を1回で比べる方法"], ["群間・群内", "群間は群どうしの違い、群内は同じ群の中でのばらつきを指す"]], "think": "なぜ1回の手続きで済むのかがカギ。ペアごとのt検定は、2群だけを見比べる作業をAB・BC・ACと何度も繰り返す必要があった。分散分析は、全部の群を一度に見渡して「群どうしのばらつき」と「群の中のばらつき」という2種類の量だけを計算し、その比を1回計算する。比べる相手を1組ずつ選び直す必要がないので、群がいくつに増えても手続きは1回のままで済む。", "vs": "t検定は「2群の平均」を比べる方法、分散分析は「3群以上の平均」を1回でまとめて比べる方法。2群だけならどちらも使えるが、3群以上になると分散分析のほうが多重性の問題(q01)を避けられる。", "why_asked": "3群以上のデータを比べる場面は農業試験・薬の効果比較・教育など幅広く出てくる。ペアごとのt検定という自然な発想がなぜ問題で、分散分析という別の方法がなぜ用意されているのかを理解する出発点になる。", "usecase": "3種類以上の商品パッケージでの売上比較、複数の教え方での試験の点数比較など、3グループ以上を同時に比べたいときに使う。", "opt": ["正解。群間のばらつきと群内のばらつきの比を見て、3群以上を1回の検定でまとめて比べるのが分散分析。", "t検定は2群だけを比べる方法。3群以上をペアごとに繰り返すと多重性の問題が起きるため、それを避けるのが分散分析。", "カイ二乗検定は、数量ではなく「人数の分布」のようなカテゴリのデータの偏りを調べる検定で、目的が異なる。", "回帰分析は、ある数値から別の数値をどれだけ予測できるかを調べる方法で、群どうしを比べる分散分析とは目的が異なる。"]}'),

  ('stats11-q03', '分散分析と多重比較',
   'ある工場で3つの生産ライン(A・B・C)の1日あたりの生産量を比べる。①同じラインでの日ごとの生産量のばらつきと、②A・B・C三つのラインの平均生産量どうしのばらつき、のうち②が①よりずっと大きいとき、何が読み取れる？',
   NULL::text,
   '["同じライン内でのばらつき（誤差）に比べて、ラインによる違いのほうが目立つと読み取れる", "ラインによる違いに比べて、同じライン内でのばらつきのほうがはるかに目立つと読み取れる", "3つのラインの生産量は、日によらずまったく同じ値になっていると読み取れる", "測定そのものの誤差が大きすぎて、比較自体ができない状態だと読み取れる"]',
   0, '[0]', 'single',
   '{"asked": "群間分散と群内分散がそれぞれ何を測っていて、群間分散のほうが大きいと何がいえるか。", "point": "群間分散(群どうしの違い)が群内分散(群の中の自然なばらつき)に比べてずっと大きいなら、群による違いが目立つといえる。", "kid": "群内分散は「同じグループの中で、値がどれくらいバラつくか」。群間分散は「グループの平均どうしが、どれくらい離れているか」。群どうしの離れ方(群間分散)が、グループの中の自然なバラつき(群内分散)より目立って大きいなら、それはグループによる違いだと考えられる。", "eg": "3つのクラスの身長を比べるとき、同じクラスの中でも1人ひとりの身長はバラつく(群内分散)。もしクラスどうしの平均身長の差(群間分散)が、そのクラス内の自然なバラつきよりずっと大きければ、「クラスによって身長の傾向が違う」と言えそうだと感じられる。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">3ラインの生産量（点=日ごとの値）</text><line x1=\"30\" y1=\"120\" x2=\"310\" y2=\"120\" stroke=\"#2a2f3f\"/><circle cx=\"65\" cy=\"55\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"78\" cy=\"62\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"58\" cy=\"66\" r=\"3.5\" fill=\"#60a5fa\"/><line x1=\"50\" y1=\"60\" x2=\"90\" y2=\"60\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"70\" y=\"42\" fill=\"#3b82f6\" font-size=\"9\" text-anchor=\"middle\">Aライン</text><circle cx=\"162\" cy=\"92\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"175\" cy=\"99\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"155\" cy=\"103\" r=\"3.5\" fill=\"#60a5fa\"/><line x1=\"147\" y1=\"97\" x2=\"187\" y2=\"97\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"167\" y=\"116\" fill=\"#3b82f6\" font-size=\"9\" text-anchor=\"middle\">Bライン</text><circle cx=\"262\" cy=\"32\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"275\" cy=\"39\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"255\" cy=\"43\" r=\"3.5\" fill=\"#60a5fa\"/><line x1=\"247\" y1=\"37\" x2=\"287\" y2=\"37\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"267\" y=\"20\" fill=\"#3b82f6\" font-size=\"9\" text-anchor=\"middle\">Cライン</text><text x=\"170\" y=\"135\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">短い線=群内分散（同じラインの中のばらつき）</text><text x=\"170\" y=\"148\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">線どうしの高さの差=群間分散（ラインどうしの違い）</text></svg>", "terms": [["群間分散", "群どうしの平均が、どれくらい離れているかを表すばらつき"], ["群内分散", "同じ群の中で、値がどれくらいバラついているかを表すばらつき"]], "think": "なぜこの2つの比を見ると「群による違いがあるか」が分かるのかがカギ。群内分散は、同じ条件(同じライン)であっても自然に生まれるバラつきの大きさを表す、いわば「ノイズ(雑音)」の大きさ。群間分散は、ライン(群)を変えたことでどれだけ平均がズレたかを表す「信号」の大きさ。信号(群間分散)がノイズ(群内分散)に比べて十分大きければ、そのズレはただの誤差では説明しきれず、ライン(群)による本当の違いだと考えられる。", "vs": "「群間分散が大きい」ことと「群内分散が小さい」ことは別の情報。片方だけを見ても「差があるか」は判断できず、必ず両方を比べて初めて意味を持つ。この比べ方の値がq04で出てくるF値。", "why_asked": "分散分析の計算の中身(なぜ2種類の分散を比べるのか)を理解していないと、F値やp値が出てきたときにただの丸暗記になってしまう。ここが分散分析の考え方の核。", "usecase": "工場のライン間の品質差の判定、複数の教室でのテスト結果の比較など、「グループの違いが、自然なばらつきを超えて意味があるか」を判断したい場面で使う。", "opt": ["正解。群間分散(ラインの違い)が群内分散(同じライン内のばらつき)よりずっと大きいなら、ラインによる違いが目立つといえる。", "群間分散と群内分散の大小関係が逆。今回は②(群どうしの違い)が①(ライン内のばらつき)よりずっと大きい設定になっている。", "群間分散が大きいことは「平均が離れている」ことを示すだけで、日ごとの値がまったく同じという意味ではない。", "群間分散が群内分散よりずっと大きいこと自体は、比較ができないことではなく、むしろ違いを読み取りやすい状態を示す。"]}'),

  ('stats11-q04', '分散分析と多重比較',
   'ある分散分析で、群間分散が12、群内分散が4だったとき、F値（F比）はいくつ？',
   NULL::text,
   '["3", "8", "16", "48"]',
   0, '[0]', 'single',
   '{"asked": "群間分散と群内分散から、F値（F比）を手で計算する。", "point": "F値＝群間分散÷群内分散。F値が大きいほど、群による差が目立つ。", "kid": "F値は、「群どうしの違いの大きさ」を「同じ群の中の自然なばらつきの大きさ」で割った数。割り算の答えが大きいほど、自然なばらつきに比べて群どうしの違いが目立つ、ということになる。", "eg": "同じクラスの中でのテストの点差(ノイズ)が10点くらいなのに対して、クラスどうしの平均点の差(信号)が50点もあれば、その差は「たまたま」では説明しにくい。F値は、この「信号がノイズの何倍あるか」を1つの数で表したもの。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">F値＝群間分散 ÷ 群内分散</text><rect x=\"40\" y=\"32\" width=\"60\" height=\"66\" fill=\"#3b82f6\"/><text x=\"70\" y=\"70\" fill=\"#e8eaf0\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"700\">12</text><text x=\"70\" y=\"112\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">群間分散</text><text x=\"127\" y=\"70\" fill=\"#e8eaf0\" font-size=\"14\" text-anchor=\"middle\">÷</text><rect x=\"155\" y=\"76\" width=\"60\" height=\"22\" fill=\"#2a2f3f\"/><text x=\"185\" y=\"91\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">4</text><text x=\"185\" y=\"112\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">群内分散</text><text x=\"242\" y=\"70\" fill=\"#e8eaf0\" font-size=\"14\" text-anchor=\"middle\">=</text><rect x=\"265\" y=\"55\" width=\"45\" height=\"38\" fill=\"#c9a04a\"/><text x=\"287\" y=\"79\" fill=\"#141720\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"700\">3</text><text x=\"287\" y=\"112\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">F値</text></svg>", "terms": [["F値（F比）", "群間分散を群内分散で割った値。群による差の目立ちやすさを表す"]], "think": "なぜ割り算をするのかがカギ。群間分散(12)は群どうしの違いの大きさ、群内分散(4)は同じ群の中の自然なばらつきの大きさ。もし群間分散が群内分散と同じくらいの大きさなら、その違いは自然なばらつきの範囲内かもしれない。群間分散を群内分散で割ることで「自然なばらつきの何倍、群どうしが離れているか」という比が出せる。今回は12÷4=3なので、群間の違いは群内のばらつきの3倍ある、ということになる。", "vs": "F値は「差」(12−4=8)ではなく「比」(12÷4=3)である点に注意。引き算にすると、群内分散の大きさそのものを基準にした「何倍か」という情報が消えてしまう。", "why_asked": "F値は分散分析の結果として最初に出てくる数で、この値をもとに「有意差があるか」を最終的に判定する(p値に変換される)。F値がどう計算されるかを知らずに大小だけ覚えると、結果の意味が分からなくなる。", "usecase": "分散分析の出力には必ずF値が表示される。複数の実験結果や複数の集団を比べるレポートで「F(2,27)=3.00」のような表記を見たときに、何を計算した数かが分かるようになる。", "opt": ["正解。群間分散12を群内分散4で割ると12÷4=3。", "12−4=8を計算してしまった場合の値。F値は引き算ではなく割り算で求める。", "群内分散4を4倍(掛け算)してしまうなど、割り算とは別の計算をした場合に出やすい値。", "12×4=48を計算してしまった場合の値。F値は掛け算ではなく割り算で求める。"], "calc": "群間分散   12\n群内分散   4\nF値       12 ÷ 4 = 3"}'),

  ('stats11-q05', '分散分析と多重比較',
   '2群を比べるt検定の帰無仮説は「2つの群の平均は同じ」だった。これを3群以上に拡張した、分散分析の帰無仮説として正しいのは？',
   NULL::text,
   '["すべての群の平均は同じである", "すべての群の分散（ばらつき）は同じである", "少なくとも1つの群の平均が、他の群と異なる", "すべての群のデータの個数は同じである"]',
   0, '[0]', 'single',
   '{"asked": "分散分析の帰無仮説と、t検定の帰無仮説との対応。", "point": "分散分析の帰無仮説は「すべての群の平均は同じ」。t検定の帰無仮説「2群の平均は同じ」を、群の数が増えても同じ形のまま拡張したもの。", "kid": "帰無仮説は「差はない、という前提」のこと。t検定では「2つの群の平均は同じ」が差がない前提だった。分散分析では群が3つ以上に増えるので、「全部の群の平均が同じ」というのが、差がない前提になる。", "eg": "3つのクラスのテストの平均点を比べるとき、「どのクラスも本当は平均点は同じで、たまたま違って見えているだけ」というのが分散分析の出発点(帰無仮説)。この前提を、データが覆せるかどうかを調べる。", "viz": "<svg viewBox=\"0 0 340 132\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">帰無仮説：すべての群の平均は同じ</text><line x1=\"40\" y1=\"60\" x2=\"300\" y2=\"60\" stroke=\"#2a2f3f\"/><line x1=\"40\" y1=\"56\" x2=\"300\" y2=\"56\" stroke=\"#60a5fa\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/><circle cx=\"90\" cy=\"56\" r=\"5\" fill=\"#3b82f6\"/><text x=\"90\" y=\"42\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">A群平均</text><circle cx=\"170\" cy=\"56\" r=\"5\" fill=\"#3b82f6\"/><text x=\"170\" y=\"42\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">B群平均</text><circle cx=\"250\" cy=\"56\" r=\"5\" fill=\"#3b82f6\"/><text x=\"250\" y=\"42\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">C群平均</text><text x=\"170\" y=\"90\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">3つとも同じ高さ（差はない）と仮に置く</text><text x=\"170\" y=\"112\" fill=\"#c9a04a\" font-size=\"9.5\" text-anchor=\"middle\">t検定の「2群の平均は同じ」を3群以上に拡張</text></svg>", "terms": [["帰無仮説", "「差はない」という、検定の出発点となる仮の前提"], ["対立仮説", "帰無仮説と逆の、「差がある」という仮説"]], "think": "なぜ「すべての」という言葉が付くのかがカギ。t検定では比べる相手が2群だけなので、「2群の平均は同じ」と言えば帰無仮説が言い尽くせた。分散分析では比べる群が3つ以上になるので、「A群とB群だけ同じ」では不十分で、比べているA・B・C…の全部の平均が同じでないと「差はない」とは言えない。だから分散分析の帰無仮説は「すべての群の平均は同じ」という、群の数ぶんまとめて否定する形になる。", "vs": "「すべての群の分散が同じ」は分散分析を行うための前提条件(等分散性)の1つであり、帰無仮説そのものとは別の話。また「少なくとも1つの群が異なる」は帰無仮説を否定したあとの対立仮説にあたる。", "why_asked": "分散分析の結果(有意差あり/なし)が何を否定し、何を仮定した上での話なのかを理解していないと、結果の意味を正しく読み取れない。t検定との対応を意識すると仕組みが繋がって見える。", "usecase": "分散分析のレポートで「帰無仮説を棄却した」と書かれているとき、それが「すべての群の平均が同じ、とは言えなくなった」ことを意味すると分かるようになる。", "opt": ["正解。t検定の「2群の平均は同じ」を、群の数が増えても同じ形のまま拡張すると「すべての群の平均は同じ」になる。", "群の分散が同じかどうかは、分散分析を行うための前提条件の1つであり、帰無仮説そのものとは別の話。", "「少なくとも1つの群が異なる」は帰無仮説を否定したあとの対立仮説の内容で、帰無仮説そのものではない。", "データの個数が群によって同じかどうかは、分散分析ができるかどうかとは別の話で、帰無仮説の内容ではない。"]}'),

  ('stats11-q06', '分散分析と多重比較',
   '3つの肥料A・B・Cで育てた野菜の重さを分散分析したところ、有意差ありという結果が出た。この結果だけから確実に言えることはどれ？',
   NULL::text,
   '["3つの群の平均が全部同じ、とは言えないというところまでしか、この結果からは分からない", "AとBの間には、はっきりとした差があるというところまで、この結果から分かる", "A・B・Cの3つは、互いにすべて異なる平均になっているというところまで、この結果から分かる", "3つのうちどの群の平均が一番大きいかというところまで、この結果から分かる"]',
   0, '[0]', 'single',
   '{"asked": "分散分析で有意差が出たとき、そこから具体的に何が分かって、何が分からないか。", "point": "分散分析の「有意差あり」は「群の平均は全部同じ、とは言えない」という意味にとどまり、どのペアが違うかまでは教えてくれない。", "kid": "分散分析は「A・B・Cの間に、どこかしら違いがありそうだ」ということまでしか教えてくれない。「AとBが違う」のか「BとCが違う」のか「3つとも違う」のか、具体的な組み合わせまでは分からない。", "eg": "クラス対抗のテストで「3クラスの平均点は全部同じ、とは言えなさそうだ」という結論が出ても、それだけでは「1組と2組の点数に差があるのか」「1組と3組なのか」までは分からない。もう一段掘り下げて調べないと、具体的にどこが違うかは見えてこない。", "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">分散分析「有意差あり」が教えてくれること</text><rect x=\"20\" y=\"30\" width=\"300\" height=\"36\" fill=\"#3b82f6\" opacity=\"0.85\"/><text x=\"170\" y=\"52\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">A・B・Cの平均は全部同じ、とは言えない</text><text x=\"90\" y=\"90\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">A と B ？</text><text x=\"170\" y=\"90\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">B と C ？</text><text x=\"250\" y=\"90\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">A と C ？</text><text x=\"170\" y=\"115\" fill=\"#c47070\" font-size=\"10\" text-anchor=\"middle\">どの組み合わせかは、ここではまだ分からない</text><text x=\"170\" y=\"132\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">→ 個別に比べ直す手続きが必要（次の設問）</text></svg>", "terms": [["有意差", "偶然では説明しにくいほど、はっきりした違いのこと"]], "think": "なぜ「どこが違うか」まで分からないのかがカギ。分散分析が計算しているのは、A・B・C全体をひとまとめにした「群どうしのばらつき」と「群内のばらつき」の比(F値)であって、AとB、BとC、AとCそれぞれの個別の差を1つずつ調べているわけではない。全体としてのばらつきが目立つ、ということが分かるだけで、そのばらつきがどのペアの差から生まれているのかは、分散分析の計算の中には出てこない。", "vs": "「有意差あり」は「差が全くない、とは言えない」という否定の否定であって、「どこがどう違うか」を教える肯定的な情報ではない。この違いを混同すると、分散分析の結果だけで「AとBが違う」と言い切ってしまう誤りを犯しやすい。", "why_asked": "分散分析で有意差が出ると、つい「特定のペアに差がある」と早合点しがち。しかしそれは分散分析だけでは分からず、別の手続きが必要になる。この限界を知らないと、結果を読み違える。", "usecase": "実験報告やレポートで「分散分析の結果、有意差が見られた」と書かれていても、それだけでは「どの組み合わせが違うか」までは主張できないと判断できるようになる。", "opt": ["正解。分散分析の有意差は「全部が同じ、とは言えない」ことを示すだけで、どのペアが違うかまでは分からない。", "分散分析の結果だけからは、AとBという特定のペアの差までは分からない。個別に比べ直す手続きが別に必要。", "3つ全部が互いに異なるとは限らない。1組だけが違って残り2つは近い、というケースも「有意差あり」に含まれる。", "どの群の平均が一番大きいかは、分散分析の結果(F値・有意差の有無)だけからは分からない。"]}'),

  ('stats11-q07', '分散分析と多重比較',
   '分散分析で「有意差あり」と分かったあと、具体的にどの群とどの群が違うのかを調べるために、群のペアを個別に比べ直す手続きを何という？',
   NULL::text,
   '["多重比較", "分散分析", "回帰分析", "カイ二乗検定"]',
   0, '[0]', 'single',
   '{"asked": "分散分析のあとで、具体的にどのペアが違うのかを調べる手続きの名前（post-hoc検定とも呼ぶ）。", "point": "分散分析で有意差ありと分かったあと、群のペアを個別に比べ直す手続きを多重比較（post-hoc検定）という。", "kid": "多重比較は、分散分析で「どこかに違いがありそう」と分かったあとに、「じゃあ具体的にAとB、BとC、AとCのどこが違うのか」を1組ずつ確かめ直す作業。", "eg": "健康診断でまず「全体的にどこか数値に異常がありそうだ」と分かってから、あらためて血液・血圧・体重と個別の項目を1つずつ検査し直すのと似ている。まず全体を見て、次に個別に絞り込む2段階の流れ。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">分散分析のあと、ペアを個別に比べ直す</text><rect x=\"90\" y=\"26\" width=\"160\" height=\"22\" fill=\"#3b82f6\"/><text x=\"170\" y=\"41\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">分散分析：有意差あり</text><line x1=\"170\" y1=\"48\" x2=\"170\" y2=\"62\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"170\" y=\"75\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">多重比較（post-hoc検定）</text><rect x=\"30\" y=\"86\" width=\"80\" height=\"20\" fill=\"#2a2f3f\"/><text x=\"70\" y=\"100\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">AとB</text><rect x=\"130\" y=\"86\" width=\"80\" height=\"20\" fill=\"#2a2f3f\"/><text x=\"170\" y=\"100\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">BとC</text><rect x=\"230\" y=\"86\" width=\"80\" height=\"20\" fill=\"#2a2f3f\"/><text x=\"270\" y=\"100\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">AとC</text><text x=\"170\" y=\"124\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">単純なt検定の繰り返しではなく、多重性を補正して比べる</text></svg>", "terms": [["多重比較（post-hoc検定）", "分散分析のあとに、群のペアを個別に比べ直す手続き"], ["ボンフェローニ補正", "多重比較の中で、比べるペアの数だけ有意水準を厳しくする代表的なやり方"]], "think": "なぜ単純なt検定の繰り返しに戻ってはいけないのかがカギ。q01で見たとおり、ペアごとにt検定を単純に繰り返すと、比較回数が増えるたびに誤って「差あり」と判定してしまう危険が積み重なる。多重比較は、この危険を承知の上で、有意水準を補正するなどの工夫をしながらペアを個別に比べ直す手続き。分散分析で「全体としてはどこかに差がありそうだ」と確認したあとに初めて、この補正付きの個別比較へ進む。", "vs": "分散分析は「全体として差があるか」を1回で判定する手続き、多重比較は「具体的にどのペアが違うか」を個別に補正しながら判定する手続き。順番としては分散分析が先、多重比較はそのあと。", "why_asked": "「有意差あり」で話を終わらせず、実際にどのペアが違うのかまで具体的に知りたい場面がほとんど。分散分析だけでは足りず、多重比較という別の手続きが必要になることを知らないと、分析が中途半端に終わってしまう。", "usecase": "3種類以上の薬・肥料・広告パターンを比べた実験で、「結局どれとどれに差があったのか」を報告するときに使う手続き。", "opt": ["正解。分散分析のあとに群のペアを個別に比べ直す手続きが多重比較（post-hoc検定）。", "分散分析は「全体としてどこかに差があるか」を1回で判定する手続きで、個別のペアの違いまでは調べない。", "回帰分析はある数値から別の数値を予測する方法で、群のペアを個別に比べ直す手続きとは目的が異なる。", "カイ二乗検定はカテゴリのデータの偏りを調べる検定で、群のペアを個別に比べ直す手続きとは別物。"]}'),

  ('stats11-q08', '分散分析と多重比較',
   '3つの群のペア(AとB、BとC、AとC)を多重比較で比べる。ボンフェローニ補正では、もとの有意水準0.05を比べるペアの数で割って厳しくする。3ペア分の補正後の有意水準はいくつ（小数第3位まで）？',
   NULL::text,
   '["0.017", "0.15", "0.05", "0.025"]',
   0, '[0]', 'single',
   '{"asked": "ボンフェローニ補正で、有意水準をペアの数に応じてどう計算し直すか。", "point": "ボンフェローニ補正＝もとの有意水準を、比べるペアの数で割る。ペアが3つなら0.05÷3。", "kid": "ボンフェローニ補正は、比べるペアが増えるほど「これくらい珍しくないと差ありと認めない」という基準を、その分だけ厳しくするやり方。ペアの数で有意水準を割り算するだけの、シンプルな工夫。", "eg": "1枚のくじで「5%より珍しいこと」を基準にしていたのを、3枚のくじを引くなら、1枚あたりの基準をもっと厳しく(珍しくしないと認めない)しておかないと、3枚のうちどれかがその基準を偶然クリアしてしまいやすくなる。その厳しくする量を、枚数(ペアの数)で割ることで決めるのがボンフェローニ補正。", "viz": "<svg viewBox=\"0 0 340 128\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">ボンフェローニ補正＝有意水準をペア数で割る</text><rect x=\"40\" y=\"32\" width=\"90\" height=\"48\" fill=\"#3b82f6\"/><text x=\"85\" y=\"60\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"700\">0.05</text><text x=\"85\" y=\"96\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">もとの有意水準</text><text x=\"155\" y=\"60\" fill=\"#e8eaf0\" font-size=\"14\" text-anchor=\"middle\">÷ 3</text><rect x=\"200\" y=\"56\" width=\"30\" height=\"24\" fill=\"#c9a04a\"/><text x=\"215\" y=\"73\" fill=\"#141720\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"700\">0.017</text><text x=\"235\" y=\"96\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">補正後（ペア1組あたり）</text></svg>", "terms": [["ボンフェローニ補正", "比べるペアの数で有意水準を割り、基準を厳しくする多重比較の代表的な方法"]], "think": "なぜ割り算で厳しくできるのかがカギ。q01・q09で見たように、比較の回数が増えるほど、どこかで偶然「差あり」と誤ってしまう危険は積み重なる。ボンフェローニ補正は、1回あたりの有意水準を比べる回数ぶん小さくしておくことで、全体としての誤りの危険をもとの0.05くらいに抑え直す、という考え方。3ペア比べるなら、1ペアあたりの基準を0.05÷3=0.0166…と、もとより厳しくしておく。", "vs": "「0.05を3倍にする」のは逆方向の操作で、基準がゆるくなってしまう。ボンフェローニ補正は基準を厳しくする(数を小さくする)ための割り算であることを取り違えないようにする。", "why_asked": "多重比較で最初に習う、最もシンプルな補正方法。仕組みが「割り算で基準を厳しくする」というだけだと分かれば、他のもっと複雑な補正方法(この先の発展的な内容)の理解の土台になる。", "usecase": "3種類以上の薬・肥料・広告パターンを多重比較で比べるとき、「どのくらい厳しい基準で有意差ありと判定するか」を決める場面で使う。", "opt": ["正解。0.05÷3=0.0166…を小数第3位までにすると0.017。", "0.05×3=0.15を計算してしまった場合の値。割り算ではなく掛け算をすると、基準がゆるくなってしまう。", "割り算をせず、もとの有意水準0.05のままにしてしまった場合の値。", "ペアの数を3ではなく2として計算してしまった場合の値（0.05÷2）。"], "calc": "有意水準     0.05\n比べるペア数  3\n補正後       0.05 ÷ 3 = 0.0166… ≒ 0.017"}'),

  ('stats11-q09', '分散分析と多重比較',
   '有意水準5%の検定を1回だけ行えば、本当は差がないのに「有意差あり」と誤る確率は5%。この検定を独立に3回繰り返すとき、少なくとも1回はうっかり「有意差あり」と誤って判定してしまう確率はどうなる？',
   NULL::text,
   '["5%より高くなる", "5%のまま変わらない", "5%より低くなる", "0%になる（誤りは起こらなくなる）"]',
   0, '[0]', 'single',
   '{"asked": "検定を繰り返すと、少なくとも1回誤って有意差ありと判定してしまう確率がどう変わるか。", "point": "検定を繰り返す回数が増えるほど、どれか1回でも誤って「差あり」と判定してしまう確率(familywise error rate)は5%より高くなる。", "kid": "1回だけなら5%の低い確率でも、同じチャンスを何回も繰り返せば、そのうちどれか1回はうっかり誤ってしまう確率はどんどん高くなっていく。これは検定に限らず、確率で起こる出来事すべてに共通する当たり前のしくみ。", "eg": "はずれくじが95本、当たりくじが5本入っている箱から1回だけ引くなら、当たる(誤ってしまう)確率は5%。でも同じ箱から3回引けば、「3回のうち少なくとも1回は当たりを引いてしまう」確率は、1回だけのときよりずっと高くなる。検定を3回繰り返すのも同じしくみ。", "viz": "<svg viewBox=\"0 0 340 134\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">検定の回数が増えるほど、誤る確率は積み上がる</text><text x=\"60\" y=\"38\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">1回だけ</text><rect x=\"30\" y=\"44\" width=\"60\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"30\" y=\"44\" width=\"6\" height=\"14\" fill=\"#c9a04a\"/><text x=\"98\" y=\"55\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"start\">約5%</text><text x=\"180\" y=\"38\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">3回繰り返す</text><rect x=\"150\" y=\"44\" width=\"60\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"150\" y=\"44\" width=\"17\" height=\"14\" fill=\"#c47070\"/><text x=\"218\" y=\"55\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"start\">5%より高い</text><text x=\"170\" y=\"90\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">「どれか1回でも誤って差ありと出る」確率が</text><text x=\"170\" y=\"108\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">回数を重ねるごとに積み重なって膨らむ</text><text x=\"170\" y=\"126\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">＝有意水準の膨張（familywise error rate）</text></svg>", "terms": [["有意水準の膨張", "検定を繰り返すたびに、どれか1回でも誤って有意差ありと判定してしまう確率が積み上がって高くなること"], ["familywise error rate", "一連の検定全体の中で、少なくとも1回誤って有意差ありと判定してしまう確率の呼び名"]], "think": "なぜ確率が積み上がるのかがカギ。1回の検定で誤らない確率は95%(100%−5%)。この「誤らない」がたまたま3回とも続く確率は、95%を3回ぶん掛け合わせた分だけ小さくなっていく。裏返すと、「誤らない」がずっと続く確率が小さくなるぶん、「3回のうちどこかで誤る」確率はそのぶん大きくなる。だから検定の回数が増えるほど、少なくとも1回は誤ってしまう確率(有意水準の膨張)は5%より高くなっていく。", "vs": "「1回あたりの有意水準は変わらず5%のまま」ということと、「3回のうちどこかで誤る確率が5%より高くなる」ことは、まったく別の話。前者は1回ごとの基準、後者は繰り返した全体で見たときの危険。この2つを混同すると、多重比較がなぜ必要なのか見えてこない。", "why_asked": "この「回数が増えると誤る危険が積み上がる」というしくみこそが、q01の多重性の問題とq07・q08の多重比較・ボンフェローニ補正が必要になる、根本の理由。ここが腹に落ちていないと、補正のやり方だけを丸暗記することになる。", "usecase": "アンケートの何十もの質問項目をそれぞれ検定にかけるとき、A/Bテストで何種類ものパターンを一度に比べるときなど、検定を何度も繰り返す分析すべてで意識しておくべき考え方。", "opt": ["正解。検定を繰り返すほど、どれか1回でも誤って差ありと判定してしまう確率は積み重なり、5%より高くなる。", "1回あたりの有意水準は5%のままでも、3回繰り返した全体で見た「どこかで誤る」確率は5%のままでは済まなくなる。", "繰り返すほど誤る確率は下がるのではなく、逆にどこかで誤ってしまう可能性が積み重なって上がっていく。", "検定を繰り返しても誤りが起こらなくなるわけではない。むしろ誤ってしまう機会が増える。"]}'),

  ('stats11-q10', '分散分析と多重比較',
   '肥料の種類(A/B)と水やりの頻度(多い/少ない)という2つの要因が野菜の生育に与える影響を同時に調べる分散分析を、二元配置分散分析という。このとき「肥料の種類の効果」「水やりの頻度の効果」以外に、両方を組み合わせると効果が変わるという現象を何という？',
   NULL::text,
   '["交互作用", "主効果", "群間分散", "多重比較"]',
   0, '[0]', 'single',
   '{"asked": "2つの要因を同時に調べる分散分析で、組み合わせによって効果が変わる現象の名前（交互作用効果ともいう）。", "point": "交互作用効果とは、2つの要因を組み合わせたときに、それぞれ単独の効果の足し算では説明できない変化が起きること。", "kid": "肥料の効果と水やりの効果を、それぞれ別々に見ているだけでは分からないことがある。「肥料Aは水やりが多いときだけよく効くけれど、水やりが少ないとあまり効かない」というふうに、組み合わせによって効果の出方が変わることを交互作用という。", "eg": "薬を飲む量と、一緒に食べるものの組み合わせのようなもの。薬だけ、食事だけならそれぞれ問題なくても、「その薬をその食事と一緒にとると効き目が変わる」ということがある。単独では見えない、組み合わせならではの効果が交互作用。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">肥料 × 水やり頻度：効果の伸び方</text><line x1=\"40\" y1=\"110\" x2=\"300\" y2=\"110\" stroke=\"#2a2f3f\"/><line x1=\"40\" y1=\"110\" x2=\"40\" y2=\"32\" stroke=\"#2a2f3f\"/><text x=\"90\" y=\"124\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">水やり少ない</text><text x=\"250\" y=\"124\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">水やり多い</text><line x1=\"90\" y1=\"90\" x2=\"250\" y2=\"42\" stroke=\"#3b82f6\" stroke-width=\"1.8\"/><circle cx=\"90\" cy=\"90\" r=\"3.5\" fill=\"#3b82f6\"/><circle cx=\"250\" cy=\"42\" r=\"3.5\" fill=\"#3b82f6\"/><text x=\"256\" y=\"38\" fill=\"#3b82f6\" font-size=\"9\" text-anchor=\"start\">肥料A</text><line x1=\"90\" y1=\"98\" x2=\"250\" y2=\"98\" stroke=\"#c47070\" stroke-width=\"1.8\"/><circle cx=\"90\" cy=\"98\" r=\"3.5\" fill=\"#c47070\"/><circle cx=\"250\" cy=\"98\" r=\"3.5\" fill=\"#c47070\"/><text x=\"256\" y=\"102\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"start\">肥料B</text><text x=\"170\" y=\"140\" fill=\"#c9a04a\" font-size=\"9.5\" text-anchor=\"middle\">2本の線が平行でない＝交互作用がある</text></svg>", "terms": [["主効果", "肥料の種類、水やりの頻度など、1つの要因だけを見たときの効果"], ["交互作用効果", "2つの要因を組み合わせたときに現れる、単独の効果だけでは説明できない変化"], ["二元配置分散分析", "2つの要因を同時に扱う分散分析。ここまでのq01〜q09は要因が1つの一元配置"]], "think": "なぜ主効果とは別に交互作用を見る必要があるのかがカギ。肥料の主効果(A対Bで生育がどれだけ違うか)と、水やりの主効果(多い対少ないでどれだけ違うか)を別々に足し合わせただけでは、「肥料Aは水やりが多いときに限って特によく効く」というような、組み合わせ特有の変化を説明できない。この足し算では説明しきれない、組み合わせによる上乗せ分やズレを、交互作用効果として別に取り出す。", "vs": "主効果は「肥料だけ」「水やりだけ」を単独で見た効果、交互作用効果は「組み合わせ方によって効果の出方が変わる」現象。両方をまとめて足りない情報にしないためには、この2つを分けて見る必要がある。", "why_asked": "現実の実験や施策は、1つの要因だけでなく複数の要因が同時に絡むことが多い。要因が1つの分散分析(一元配置)だけでは見えない「組み合わせの効果」があることを、軽くでも知っておくと、実験のデザインの幅が広がる。", "usecase": "薬の種類と投与量の組み合わせ、広告のデザインと配信時間帯の組み合わせなど、2つ以上の条件を同時に変えて効果を調べる実験計画で使われる考え方。", "opt": ["正解。2つの要因を組み合わせたときに、単独の効果だけでは説明できない変化が現れることを交互作用効果という。", "主効果は肥料や水やりなど1つの要因だけを見た効果で、組み合わせによる変化を指す交互作用とは別物。", "群間分散は分散分析の中で群どうしのばらつきを表す量であり、2要因の組み合わせ効果を指す言葉ではない。", "多重比較は分散分析のあとに個別のペアを比べ直す手続きで、要因どうしの組み合わせ効果を指す言葉ではない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
